if(u.type.id==='soldier'){ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,0,7*s,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#e7e5cd';ctx.lineWidth=2*s;ctx.beginPath();ctx.moveTo(3*s,0);ctx.lineTo(13*s,0);ctx.stroke();ctx.fillStyle='#dfd5ae';ctx.beginPath();ctx.arc(0,-2*s,2.4*s,0,Math.PI*2);ctx.fill()}
