else{ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(-13*s,-9*s,26*s,18*s,5*s);ctx.fill();ctx.fillStyle='#313c31';ctx.fillRect(-9*s,-7*s,9*s,14*s);ctx.fillStyle='#d9dfc2';ctx.fillRect(3*s,-1.3*s,17*s,2.6*s);ctx.fillStyle='#222a22';ctx.beginPath();ctx.arc(-7*s,-9*s,2.5*s,0,Math.PI*2);ctx.arc(-7*s,9*s,2.5*s,0,Math.PI*2);ctx.fill()}
