// Open training-ground clearing and worn tracks
ctx.fillStyle='#829064';ctx.beginPath();ctx.ellipse(900,625,680,440,-.08,0,Math.PI*2);ctx.fill();ctx.fillStyle='#879367';ctx.beginPath();ctx.ellipse(900,625,490,300,.12,0,Math.PI*2);ctx.fill();
ctx.strokeStyle='#9b9870';ctx.lineWidth=44;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-80,1000);ctx.bezierCurveTo(350,890,380,1090,820,855);ctx.bezierCurveTo(1080,715,1320,800,1890,420);ctx.stroke();ctx.strokeStyle='#b0a47a';ctx.lineWidth=3;ctx.setLineDash([12,18]);ctx.stroke();ctx.setLineDash([]);
ctx.strokeStyle='#6d7952';ctx.lineWidth=2;for(let x=0;x<W;x+=100){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=0;y<H;y+=100){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}
for(const rock of rocks){ctx.fillStyle='#777b63';ctx.beginPath();ctx.ellipse(rock.x,rock.y,rock.r*1.35,rock.r,.4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#94947a';ctx.beginPath();ctx.arc(rock.x-rock.r*.25,rock.y-rock.r*.25,rock.r*.38,0,Math.PI*2);ctx.fill()}
for(const t of trees){ctx.fillStyle='#263a2b55';ctx.beginPath();ctx.ellipse(t.x+5,t.y+7,t.r*1.2,t.r*.75,t.a,0,Math.PI*2);ctx.fill();ctx.fillStyle='#304d34';ctx.beginPath();ctx.arc(t.x,t.y,t.r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#3d6040';ctx.beginPath();ctx.arc(t.x-t.r*.22,t.y-t.r*.28,t.r*.62,0,Math.PI*2);ctx.fill();ctx.fillStyle='#607448';ctx.beginPath();ctx.arc(t.x+t.r*.23,t.y+t.r*.17,t.r*.28,0,Math.PI*2);ctx.fill()}
