for(const u of units){if(u.order){ctx.strokeStyle=u.team==='blue'?'#d7e9ae88':'#ef9b8588';ctx.lineWidth=1.5;ctx.setLineDash([5,6]);ctx.beginPath();ctx.moveTo(u.x,u.y);ctx.lineTo(u.order.x,u.order.y);ctx.stroke();ctx.setLineDash([])} }
for(const sh of shots){ctx.strokeStyle=sh.color;ctx.globalAlpha=.85;ctx.lineWidth=sh.splash?3:2;ctx.beginPath();ctx.moveTo(sh.x,sh.y);ctx.lineTo(sh.x-sh.dx*8,sh.y-sh.dy*8);ctx.stroke();ctx.globalAlpha=1}
