for(const u of units){const friendly=u.team==='blue',c=friendly?u.t.color:'#d87362';ctx.save();ctx.translate(u.x,u.y);ctx.rotate(u.a);ctx.fillStyle='#19211888';ctx.beginPath();ctx.ellipse(2,4,u.t.r*1.3,u.t.r*.9,0,0,Math.PI*2);ctx.fill();if(selected.includes(u)){ctx.strokeStyle='#e2f5af';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,u.t.r+7,0,Math.PI*2);ctx.stroke()}
