const base='http://127.0.0.1:9222';
let r=await fetch(base+'/json/new?file:///home/runner/work/PlayGround/PlayGround/index.html',{method:'PUT'});
let target=await r.json();
const ws=new WebSocket(target.webSocketDebuggerUrl);
await new Promise((ok,no)=>{ws.onopen=ok;ws.onerror=no});
let id=0, pending=new Map(), errors=[];
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.text);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
const send=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))});
await send('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
await send('Page.enable');await send('Runtime.enable');await send('Page.navigate',{url:'file:///home/runner/work/PlayGround/PlayGround/index.html'});
await new Promise(r=>setTimeout(r,2300));
const shot=await send('Page.captureScreenshot',{format:'jpeg',quality:85,fromSurface:true});
const fs=await import('node:fs/promises');await fs.writeFile('/tmp/opencode/latest.jpg',Buffer.from(shot.result.data,'base64'));
console.log('saved jpeg',Buffer.from(shot.result.data,'base64').length,'bytes; runtime exceptions:',errors);
const evalResult=await send('Runtime.evaluate',{expression:'JSON.stringify({friends:document.querySelector("#friends").textContent,foes:document.querySelector("#foes").textContent,cards:document.querySelectorAll(".unit").length,canvas:[document.querySelector("#game").width,document.querySelector("#game").height]})',returnByValue:true});
console.log('runtime state:',evalResult.result.result.value);ws.close();
